    faq_a_nm_me1_guide: "Sky – New Me میں آپ کا کردار، اپنی پہلی شکل (Sky 1) میں۔ پہلی بار، شامل ہوتے ہی، چاروں طرف چمک بکھیرتا روشنی کا ایک پورٹل کھلتا ہے اور اس میں سے Sky اڑ کر نکلتا ہے، چند ٹیپ میں بتاتا ہے کہ آگے کیا ہے، اور پھر ہر سوال کے پاس رہتا ہے: کھانے چنتے وقت یہ آپ کے ساتھ اپنی کتاب میں لکھتا ہے، اور اس کے مشورے پر ٹیپ کرنے سے ایک اور مشورہ دکھائی دیتا ہے۔ آخر میں Sky آپ کے ساتھ جشن مناتا ہے اور ایک مختصر ٹور پر لے جاتا ہے – اور ٹور ختم ہونے پر اس کے پاس آپ کے ساتھ ایک اور چھوٹا سا لمحہ ہوتا ہے۔ اگر بیچ میں ہی – سوالوں یا ٹور کے دوران – باہر نکل جائیں، تو اگلی بار Sky آپ کو دیکھ کر خوش ہوتا ہے اور پوچھتا ہے کہ کیا اسی جگہ سے آگے بڑھیں۔",
