    nm_m1_tip_ai: "کوئی کھانا فہرست میں نہیں؟ بعد میں \"تبدیل کریں\" میں اسے اپنے الفاظ میں لکھا جا سکتا ہے – اور AI اس کا حساب لگا لے گا۔ اور اب، مل کر چنیں کہ ہر دن کیا کھانا ہے۔",
    nm_m1_tip_love: "اور اگر کوئی چیز پسند نہ ہو – تو اسے ہمیشہ AI سے بدلا جا سکتا ہے۔ کھانا کوئی بھی ہو – اگر آپ کو پسند ہے تو وہ مینو میں رہتا ہے۔",
    nm_m1_tip_rice: "مجھے چاول سب سے زیادہ پسند ہیں – یہی میری بنیاد ہوں گے، اس لیے میں انہیں چنوں گا۔ میرا مشورہ ہے کہ وہی چنا جائے جو جانا پہچانا اور مزیدار ہو۔",
    faq_a_shop_basics: "جب خریداری کی فہرست بالکل خالی ہو – مثلاً بالکل شروع میں – تو شروعات کے لیے ایک بنیادی فہرست دکھائی دیتی ہے: دودھ، ڈبل روٹی، انڈے اور بہت کچھ۔ کسی چیز پر ایک ٹیپ اسے فہرست میں شامل کر دیتا ہے، اور “سب شامل کریں” سب کچھ ایک ساتھ شامل کر دیتا ہے۔ جیسے ہی فہرست میں کچھ آ جاتا ہے، یہ بنیادی فہرست غائب ہو جاتی ہے۔",
