    room_genie_rest: "جنگل کی روح ابھی آرام کر رہی ہے – کل دوبارہ آئیے ✨",
    faq_a_shop_holidays: "خریداری کی فہرست میں تحفے پر ٹیپ کریں: آپ کے ملک (جو ترتیبات میں منتخب ہے) کے تہوار ترتیب سے، اپنی تاریخوں کے ساتھ دکھائی دیتے ہیں – جو ہر سال خود بخود طے ہوتی ہیں۔ کسی تہوار پر ٹیپ کرنے سے ان چیزوں کی تیار فہرست کھلتی ہے جو لوگ اس کے لیے خریدتے ہیں؛ سب کچھ منتخب ہوتا ہے (سوائے اس کے جو پہلے سے آپ کی فہرست میں ہے)، جو نہیں چاہیے اس کا نشان ہٹائیں اور “فہرست میں شامل کریں” پر ٹیپ کریں۔ تہوار سے دو ہفتے پہلے فہرست کے اوپر ایک چھوٹا کارڈ دکھائی دیتا ہے؛ ✕ اسے اگلے تہوار تک چھپا دیتا ہے۔",
    faq_q_shop_holidays: "“تہوار کے لیے کیا خریدیں” کیسے کام کرتا ہے؟",
    shop_hol_add: "فہرست میں شامل کریں ({n})",
