    shop_hol_btn: "تہوار کے لیے کیا خریدیں",
    shop_hol_items_title: "{holiday} – کیا خریدیں؟",
    shop_hol_not_now: "ابھی نہیں",
    faq_a_shop_delivery: "خریداری کی فہرست میں ٹرک پر ٹیپ کریں: منتخب کریں کہ ڈیلیوری میں کیا ہے (سب کچھ پہلے سے منتخب ہوتا ہے)، وہ کب پہنچے گی – آج، کل یا کوئی اور دن – اور کس وقت (صبح، دوپہر، شام، یا اپنا وقت چننے کے لیے “دیگر…”)۔ وہ چیزیں دن اور اوقات کے ساتھ فہرست کے اوپر “راستے میں” کارڈ میں چلی جاتی ہیں۔ جب وہ دن آتا ہے تو میرا دن میں “کیا ڈیلیوری پہنچ گئی؟” دکھائی دیتا ہے (اور کارڈ پر “پہنچ گئی؟” ہوتا ہے)۔ اگر سب کچھ پہنچ گیا تو وہ “دوبارہ خریدیں” میں چلی جاتی ہیں۔ اگر کچھ کم ہے تو جو نہیں پہنچا اس پر ٹیپ کریں – وہ سیدھا فہرست میں واپس آ جاتا ہے۔",
    faq_a_shop_departments: "فہرست خود بخود سپر مارکیٹ کے شعبوں کے حساب سے ترتیب پا جاتی ہے – پھل اور سبزیاں، روٹی، ڈیری اور انڈے، گوشت اور مچھلی، راشن، فروزن، مشروبات، اسنیکس، صفائی، ذاتی نگہداشت، بچوں کا سامان اور پالتو جانور – تاکہ گلیاروں میں ترتیب سے گھوما جا سکے۔ شعبہ چیز کے نام سے پہچانا جاتا ہے۔ اگر کوئی چیز غلط جگہ چلی گئی ہو تو اس پر ٹیپ کر کے اس کا شعبہ منتخب کریں، یا اپنا شعبہ لکھنے کے لیے “دیگر…” منتخب کریں۔",
    faq_a_shop_share_qty: "جی ہاں۔ ہر چیز کے ساتھ، + ایک اور بڑھاتا ہے (×2، ×3…) اور − ایک کم کرتا ہے۔ خریداری کی فہرست کے اوپر شیئر کا بٹن پوری فہرست کو، شعبوں کے حساب سے صاف ستھرے انداز میں ترتیب دے کر، WhatsApp، ای میل یا کاپی کے ذریعے بھیجتا ہے۔",
    faq_a_shop_two_buttons: "دونوں کا مطلب ہے “خرید لیا”۔ ✕ اس چیز کے لیے ہے جو ایک ہی بار خریدی جاتی ہے – وہ فہرست سے ہٹ جاتی ہے (اور غلطی کی صورت میں کام آنے کے لیے 🗑️ آرکائیو میں انتظار کرتی ہے)۔ ↺ ان چیزوں کے لیے ہے جو بار بار خریدی جاتی ہیں – وہ فہرست سے ہٹ کر “دوبارہ خریدیں” میں انتظار کرتی ہے: اسے فہرست کے سب سے نیچے کوڑے دان کے ساتھ والا چھوٹا ↺ بٹن کھولتا ہے، اور وہاں ایک ٹیپ کسی چیز کو واپس فہرست میں ڈال دیتا ہے۔ اس کے اندر “ترمیم” سے کسی چیز کو اس میں سے ہٹایا جا سکتا ہے۔ کوئی چیز شامل کرتے وقت، پہلے خریدی گئی چیزیں تجاویز کے طور پر دکھائی دیتی ہیں، اور اگر وہ پہلے سے فہرست میں ہو تو دوسری لائن بننے کے بجائے بس ×2 ہو جاتی ہے۔",
