    faq_a_new_me_challenge_journal: "جب کوئی چیلنج ختم ہوتا ہے – بڑا، منی یا ہفتے کا چیلنج – تو جشن میں 📝 کیسا رہا؟ بٹن ہوتا ہے۔ یہ چیلنج ڈائری میں ایک صفحہ کھولتا ہے: کیسا محسوس ہوا (پانچ چہرے)، کس چیز نے مدد کی، کیا مشکل تھا اور اس سے آگے کیا ساتھ لے جائیں – ان میں سے کچھ بھی لازمی نہیں، اور اسے بعد کے لیے بھی چھوڑا جا سکتا ہے۔ ڈائری جادوئی بیگ میں ایک ہیرا ہے: ہر ختم ہونے والا چیلنج، اس کی تاریخ اور جو لکھا گیا، سب سے نیا سب سے اوپر – کسی ایک پر ٹیپ کریں اور اسے پڑھیں، بدلیں یا شیئر کریں (صرف وہی شیئر ہوتا ہے جو صفحے پر ہے)۔ ختم ہونے والے چیلنج کو کامیابیوں میں ایک تمغہ بھی ملتا ہے، “چیلنجز جو میں نے پورے کیے” کے تحت۔ چیلنج ڈائری عام ڈائری سے الگ ہے۔",
