    faq_a_ai_reminder_in_text: "جی ہاں – اسے کام کے ساتھ ہی لکھ دیں، مثلاً “کل 17:00 بجے پارسل لینا، ایک گھنٹہ پہلے یاد دہانی کے ساتھ”۔ یاد دہانی کام پر ہی محفوظ ہو جاتی ہے: ایک گھنٹہ پہلے، آدھا گھنٹہ پہلے، ایک دن پہلے وغیرہ، اور بغیر وقت کے “مجھے یاد دلانا” کا مطلب ہے 10 منٹ پہلے۔ متن میں لکھی گئی یاد دہانی کو اسی ونڈو کے یاد دہانی والے خانے پر ترجیح ملتی ہے۔",
