    books_home_save: "محفوظ کریں",
    faq_a_books_home_chip: "جی ہاں۔ مطالعے کے گوشے میں، جو کتاب پڑھی جا رہی ہو اس کے کارڈ پر 📌 ہوم اسکرین پر کو چھوئیں۔ ہوم اسکرین پر سلام کے نیچے کتاب اور صفحے کے ساتھ ایک چھوٹا بٹن نظر آتا ہے – اسے چھوئیں، نیا صفحہ نمبر لکھیں اور محفوظ کریں، اور پیش رفت درج ہو جاتی ہے (مطالعے کے گوشے میں بھی)۔ 📌 کو دوبارہ چھونے سے وہ ہٹ جاتی ہے۔ کئی کتابیں ایک ساتھ ہو سکتی ہیں – ہر ایک کا اپنا بٹن – اور یہ ہر ڈیوائس پر ایک جیسا رہتا ہے۔",
    faq_a_new_me_week_challenge: "ایک ہفتے کا چھوٹا چیلنج، جسے خود چنا جاتا ہے۔ راہداری میں ایک بڑا کارڈ ہے: “اس ہفتے کس پر کام کرنا ہے؟” – اسے چھوئیں، ایک شعبہ چنیں (اپنے ساتھ، دوسروں کے ساتھ، سیکھنا اور آگے بڑھنا، سکون، ہمت کے چھوٹے قدم، گھر اور روٹین) اور ایک چیلنج، اور طے کریں کہ کب شروع ہو۔ یہی چیلنجز چیلنجز کی اسکرین میں بھی ہیں، 🌱 ذاتی ترقی کے تحت۔ ہر روز کارڈ پر ✓ لگائیں (ہفتے میں ایک دن کی چھوٹ)، اور ہر ختم ہونے والا ہفتہ خفیہ دنیا کے لیے ایک نئی چابی لاتا ہے۔ “روزانہ 2 صفحات پڑھنا” مطالعے کے گوشے میں درج صفحات سے خود نشان زد ہو جاتا ہے۔ ہفتہ ختم ہونے پر 📌 روزانہ کے کام کے طور پر رکھیں اسے آپ کے چنے ہوئے وقت پر میری روٹین میں شامل کر دیتا ہے، ہر روز ✓ کے ساتھ۔ ایک وقت میں ہفتے کا ایک ہی چیلنج چلتا ہے؛ بڑے اور چھوٹے چیلنجز اس کے ساتھ جاری رہتے ہیں۔",
    faq_a_room_genie: "سمندر کے سامنے والے برآمدے میں علاءالدین کے چراغ کو چھونے سے جنگل کی روح باہر آتی ہے – اور ایک بات چیت شروع ہوتی ہے: آپ کی خواہش کیا ہے (زندگی میں کس تبدیلی کی آرزو ہے)، پوری ہونے پر کیسا لگے گا، راستے میں کیا مشکل ہے، اور اس وقت کی صورتِ حال کو کیسے اچھائی میں بدلا جا سکتا ہے۔ پھر تقریباً کتنا وقت لگے گا، ایک پہلا چھوٹا قدم اور دو مزید، اور مشکل لمحوں کے لیے ایک “اگر… تو…”۔ آخر میں پوری خواہش قدم بہ قدم سامنے آتی ہے، اور اسے میرے اہداف میں ہدف بنایا جا سکتا ہے (قدم راستے کے مراحل بن جاتے ہیں، چنے ہوئے وقت کے مطابق تاریخ کے ساتھ؛ وہاں سب کچھ بدلا جا سکتا ہے) یا ڈائری میں محفوظ کیا جا سکتا ہے – اور پھر روح رخصت ہو جاتی ہے۔ ان میں سے کوئی ایک نہ چنا جائے تو کچھ بھی محفوظ نہیں ہوتا۔ دوسری بار سے، روح پہلے پوچھتی ہے کہ کیا زندگی میں کچھ اور بدلنے کی آرزو ہے: ہاں – وہی بات چیت؛ ابھی نہیں – پہلے سے طے شدہ اہداف کو پورا کرنے کی یاد دہانی۔ روح دن میں ایک بار باہر آتی ہے: خواہش محفوظ ہونے کے بعد (یا “ابھی نہیں” کے بعد)، وہ کل تک آرام کرتی ہے۔ سوالات خواہش کو منصوبے میں بدلنے کے ایک معروف طریقے پر مبنی ہیں: خواہش، نتیجہ، رکاوٹ اور منصوبہ۔",
