    nm_me_choose: "چنیں",
    nm_me_on_screen: "اسکرین پر",
    faq_a_new_me_game: "New Me میں کھیل کے بٹن ہمیشہ ایک ہی جگہ رہتے ہیں – راہداری میں، خفیہ کمرے میں اور جنگل میں ہر جگہ؛ صرف درمیان والی پینٹنگ بدلتی ہے۔ اوپر: سفر کا دن، چابیاں، سلسلہ اور آج کی توانائی (پلان میں سے کتنا کھایا جا چکا ہے)، اور اس کے نیچے اگلا مشن – اگلا کھانا اپنے وقت پر (ٹیپ کرنے سے کھلتا ہے، ✓ کھا لیا کے ساتھ)۔ ایک طرف: پورا دن، چیلنجز اور میرا سفر، اور ان کے ساتھ ہفتے کا چیلنج – اس کے 7 دن اور آج کے لیے ✓۔ نیچے: جادوئی بیگ (پورا New Me – دنیا کا نقشہ، میرا سفر، خریداری، کامیابیاں، چیلنج ڈائری، پیمائشیں، تصاویر، ماہانہ کیلنڈر، روزانہ جدول، یاد دہانیاں، مینو PDF اور ترتیبات؛ یہ اپنی الگ اسکرین کے طور پر کھلتا ہے)۔ دنیا کا نقشہ، جو بیگ میں سب سے پہلے ہے، جنگل کی ہر جگہ دکھاتا ہے – کسی جگہ پر ٹیپ کریں اور وہاں پہنچ جائیں؛ بند جگہ پر نظر آتا ہے کہ اسے کتنی چابیاں چاہییں۔ Sky جنگل کی پگڈنڈی پر آپ کا کردار ہے: یہ Sky 1 سے شروع ہوتا ہے، چند چیلنجز کے بعد (4 چابیاں) بڑا ہو کر Sky 2 بن جاتا ہے اور آخر کے قریب (9 چابیاں) Sky 3 – ایک ایسے نئے روپ کے ساتھ جو آنکھوں کے سامنے ہوتا ہے۔ ہر مرحلہ دیکھنے کے لیے Sky پر ٹیپ کریں – جو مرحلہ پہلے مل چکا ہو اسے دوبارہ چنا جا سکتا ہے، اس لیے پچھلا مرحلہ واپس آ سکتا ہے۔ Sky تیرتا ہے – اسے انگلی یا ماؤس سے کھینچا جاتا ہے، اور جس داخلے کو یہ چھوئے وہ کھل جاتا ہے (بند داخلے پر لکھا ہوتا ہے کہ کتنی چابیاں کم ہیں)۔ Sky ہر کمرے اور ہر جگہ میں بھی ساتھ آتا ہے اور جہاں آپ اسے چھوڑیں وہیں تیرتا رہتا ہے: اسے کہیں بھی کھینچیں، اور اس کے نیچے چمکتے دائرے کو کھینچ کر اسے پورا گھمائیں؛ یہ اسی سمت منہ کرتا ہے جدھر چلتا ہے (کمپیوٹر پر: تیر اسے چلاتے ہیں، Q اور E اسے گھماتے ہیں)۔ راہداری میں، اوپری بار کے نیچے موجود چھوٹا 🏠 ہوم اسکرین پر واپس لے جاتا ہے؛ ہر کمرے اور ہر جگہ میں، اسی کونے والا بٹن راہداری میں واپس لے جاتا ہے۔",
