    faq_a_new_me_menu_build: "پہلے سوالنامہ پوچھتا ہے کہ کون سے کھانے کب کھائے جاتے ہیں (2 کھانے + ایک اسنیک، 2 کھانے + ہلکا رات کا کھانا، یا دونوں)، اور کیا شام کو کچھ ہوتا ہے – کھانے کو یا پینے کو، کیا، اور کس وقت۔ “2 کھانے + ایک اسنیک” میں کھانے دوپہر کا کھانا (11:30) اور رات کا کھانا (19:00) ہیں، اور اسنیک 16:00 پر۔ پھر ان کھانوں کے تمام اختیارات سامنے آتے ہیں۔ ہر کھانے کے لیے 2 پسندیدہ تک چنیں – مینو میں “یہ یا وہ” لکھا آتا ہے۔ کچھ اختیارات میں (پیٹا اور اسپریڈ، کارن فلیکس اور دودھ، کچھ ہلکا) اپنی پسند کی 3 تک چیزیں چنی جاتی ہیں، ہر ایک اپنی مقدار میں، اور مینو میں “یہ یا وہ یا وہ” لکھا آتا ہے؛ کیلوریز انتخاب کے مطابق ہوتی ہیں۔ کافی اور مشروبات بھی اسی طرح کام کرتے ہیں۔ ہر انتخاب متوازن ہوتا ہے، اس لیے دن کا مجموعہ ٹھیک 1,300 یا 1,500 بنتا ہے۔ کسی بھی وقت بدلنے کے لیے: ⚙️ ترتیبات ← 🍽️ اپنا مینو بنائیں، یا کھانے کے کارڈ پر “جو پسند ہوں، 3 تک چنیں”۔",
