    faq_a_myday_water_toggle: "جی ہاں۔ 'میرا دن' میں پانی کا گلاس (ایک اور گلاس کے لیے + کے ساتھ) پہلے سے دکھائی دیتا ہے۔ اسے چھپانے کے لیے ترتیبات > تخصیص اور کیلنڈر میں \"'میرا دن' میں پانی دکھائیں\" بند کریں۔ کچھ بھی حذف نہیں ہوتا – پانی کی نگرانی چلتی رہتی ہے، اور دوبارہ آن کرنے پر گلاس واپس آ جاتا ہے۔",
