    faq_a_food_list_languages: "بلٹ اِن کھانوں کی فہرست اسرائیلی کھانوں اور ان کے عبرانی ناموں سے شروع ہوئی تھی۔ باقی تمام زبانوں میں ہر کھانا اپنے انگریزی نام سے دکھتا ہے، اور تلاش ہر وہ انگریزی نام ڈھونڈ لیتی ہے جو اسے معلوم ہو (مثلاً 'broth' سے Clear soup ملتا ہے)؛ جن کھانوں کا صرف عبرانی نام ہے وہ وہاں نظر نہیں آتے۔ جو فہرست میں نہیں، اسے بس اپنے الفاظ میں لکھ دیں – AI کا اندازہ ہر زبان میں کام کرتا ہے۔",
