    workout_ready_replace_btn: "تبدیل کریں",
    faq_a_sport_workout_ai: "\"میری ورزشیں\" ← ⋯ ← \"AI سے پلان\" (اور جب ٹیبل خالی ہو تو تیار پلانوں کے ساتھ والے ٹائل پر بھی)۔ چند ٹیپ سے جواب دیں – ہفتے میں کتنی بار، کب، جگہ، سطح اور ہدف، تقریباً سب میں \"دیگر\" بھی ہے – اور چاہیں تو ایک آزاد سطر لکھیں، جیسے حساس گھٹنا یا گرمیوں تک 5 کلومیٹر دوڑنا۔ AI پورا ہفتہ بناتا ہے: ورزش کی اقسام، دن، اوقات، دورانیہ، شدت، مشقیں اور آرام کے دن۔ کچھ بھی محفوظ ہونے سے پہلے پیش نظارہ آتا ہے: \"میری ٹیبل میں ڈالیں\" (ٹیبل کی جگہ یا اس کے ساتھ)، \"دوسرا مشورہ\" (3 بار تک) یا \"جواب بدلیں\"۔ پلان جان بوجھ کر معتدل رکھا جاتا ہے، اور اگر آپ درد یا چوٹ کا ذکر کریں تو نرم انتخاب اور کسی ماہر سے مشورہ کرنے کی تجویز ملتی ہے۔ یہ شیڈول اور روٹین والے AI کا ہی کوٹا استعمال کرتا ہے: 5 بار مفت، اور پریمیم میں مہینے میں 60 بار۔",
