    faq_a_sport_workout_jar: "ہر قسم کی ورزش کا اپنا رنگین ستارہ ہے – دوڑ گلابی، چہل قدمی سبز، تیراکی نیلا وغیرہ۔ اس ہفتے درج کی گئی ہر ورزش، ٹیبل سے یا الگ سے، اپنا ستارہ \"میری ورزشیں\" کے اوپر والے مرتبان میں ڈال دیتی ہے، اور مرتبان ہفتہ وار ہدف تک بھرتا جاتا ہے (ہدف بدلنے کے لیے اسے چھوئیں)۔ ہدف پورا ہونے پر مرتبان چمک اٹھتا ہے۔ ساتھ والا چھوٹا مرتبان گنتا ہے کہ لگاتار کتنے ہفتے وہ بھرا۔",
    faq_q_sport_workout_jar: "\"میری ورزشیں\" میں رنگین ستارے اور مرتبان کیا ہیں؟",
    faq_a_sport_workout_gcal: "جی ہاں – ⋯ ← Google کیلنڈر میں (ترتیبات میں Google کیلنڈر جوڑنے کے بعد)۔ وقت والی ہر ورزش اپنے دنوں پر ہر ہفتے دہرائے جانے والا ایونٹ بن جاتی ہے، اور ایپ میں تبدیلیاں اسے بھی اپ ڈیٹ کرتی ہیں۔ یاد دہانیاں صرف ایپ سے آتی ہیں، اس لیے Google اپنی یاد دہانیاں شامل نہیں کرتا، اور ورزشیں ایپ میں کبھی دو بار نہیں آتیں۔ دوبارہ چھونے سے Google کیلنڈر سے صرف ورزشیں ہٹتی ہیں۔",
    faq_q_sport_workout_gcal: "کیا میری ورزشیں Google کیلنڈر میں دکھ سکتی ہیں؟",
    workout_gcal_btn: "Google کیلنڈر",
    workout_gcal_error: "Google کیلنڈر اپ ڈیٹ نہیں ہو سکا – اگلی تبدیلی پر دوبارہ کوشش ہوگی",
    workout_gcal_not_connected: "پہلے ترتیبات میں Google کیلنڈر جوڑیں",
    workout_gcal_off_toast: "ورزشیں Google کیلنڈر سے ہٹا دی گئیں",
