    faq_a_notes_sticky_look: "نوٹس شیشے کے کارڈوں کی ایک مختصر فہرست ہیں – نوٹس کے اوپر 🎨 سارے نوٹس کی شکل بدلتا ہے: فہرست، اوپر دنوں کے بٹن اور وہ ونڈو جس میں نوٹ لکھا جاتا ہے – شیشہ، صاف فہرست، انڈیکس کارڈ یا واشی ٹیپ۔ جس نوٹ کو کھینچا جا رہا ہو وہ بالکل اپنی ہی شکل اور رنگ میں رہتا ہے۔ کسی نوٹ کو کھولنے کے لیے اس کے متن پر ٹیپ کریں – وہاں اسے بدلا جا سکتا ہے، اس کے رنگ بدلے جا سکتے ہیں اور دیکھا جا سکتا ہے کہ یہ آخری بار کب لکھا گیا۔ کام ہو جائے تو ○ پر ٹیپ کریں، اور × اسے آرکائیو میں بھیج دیتا ہے (فہرست کے نیچے 🗑️ سے واپس آ جاتا ہے)۔ ترتیب بدلنے، “بعد میں” کے نیچے لے جانے یا اوپر کسی دن پر رکھنے کے لیے ⠿ سے کھینچیں۔ ! نوٹ کو فوری کے طور پر نشان زد کرتا ہے – وہ آہستہ سے اوپر کی پہلی قطاروں میں چلا جاتا ہے، ایک چھوٹے “فوری” ٹیگ کے ساتھ؛ دوبارہ ٹیپ کرنے سے نشان ہٹ جاتا ہے۔",
