    faq_a_routine_clash: "اگر اسی وقت انہی دنوں میں پہلے سے کوئی چیز ہو تو دو انتخاب آتے ہیں: \"بدلیں\" – نئی چیز اس وقت پر آ جاتی ہے اور پہلے والی کے لیے دوسرا وقت چنا جاتا ہے (کسی موجودہ چیز میں ترمیم کرتے وقت اس کا پچھلا وقت تجویز ہوتا ہے، تاکہ دونوں بس آپس میں بدل جائیں)، یا \"دونوں\" – دونوں ایک ہی وقت پر رہتی ہیں، ایک دوسری کے نیچے۔ اگر دن مختلف ہوں (مثلاً ایک اتوار سے جمعرات اور دوسری جمعہ) تو کچھ نہیں پوچھا جاتا۔",
