    faq_a_secret_room_yoga: "جنگل کی پگڈنڈی کے آخر میں ایک چمکتا ہوا دروازہ ہے، اور اس کے پیچھے، ایک آبشار کے پاس، جنگل کی مخلوقات – لومی، پفی، نکسی اور اسپارکلٹ – آدھے دائرے میں اپنی چٹائیوں پر بیٹھی ہیں، اور یوگا ٹیچر فلورا ان کے سامنے پتھر پر رکھی اکیلی چٹائی پر بیٹھی ہیں۔ فلورا پر ٹیپ کریں: وہ آنکھیں کھولتی ہیں، سب کچھ قریب آ جاتا ہے، اور گفتگو آہستہ آہستہ، پڑھنے کا وقت دیتے ہوئے شروع ہوتی ہے – فلورا پوچھتی ہیں کہ سب کیسے ہیں، ہر مخلوق اپنی زبانی جواب دیتی ہے (ہر سطر کے ساتھ بولنے والے کی ایک چھوٹی سی تصویر ہوتی ہے)، اور پھر وہ آپ سے پوچھتی ہیں کہ اپنے قریبی لوگوں کے ساتھ کیسا محسوس ہوتا ہے۔ گفتگو آپ کے جوابوں کے مطابق آگے بڑھتی ہے – اچھے لوگ، کوئی مشکل شخص، یا تھوڑا اکیلا پن۔ ہر راستہ ایک چھوٹے مشن (جو سیدھا میرا دن میں شامل ہو سکتا ہے؛ جب مشن کچھ لکھنے کا ہو تو لکھنے کی جگہ ہوتی ہے، اور لکھا ہوا جادوئی ڈائری میں محفوظ ہو جاتا ہے) اور ساتھ میں تین سانسوں والے آسن پر ختم ہوتا ہے۔ ↩ ایک قدم پیچھے لے جاتا ہے اور ✦ نئی گفتگو شروع کرتا ہے۔ اگلی چابی آبشار کھولتی ہے: پتھر پر بیٹھتے ہی سب کچھ چھپ جاتا ہے اور صرف پانی کی آواز رہ جاتی ہے۔ تالاب پر جھکتے ہی پانی سے ایک سوال ابھرتا ہے – آپ کا اصل روپ آج کیا کرتا؟ – اور جواب 'میرا دن' میں ایک چھوٹا کام بن جاتا ہے۔ یہ ایک پیارا لمحہ ہے، کسی ماہر سے بات کرنے کا متبادل نہیں۔",
