    faq_a_routine_ai: "میری روٹین میں ⚙️ (یا ➕) کھولیں اور \"AI سے نئی روٹین\" دبائیں: روٹین کو آسان الفاظ میں لکھیں – مثلاً \"7 بجے اٹھنا، 8 بجے جم، 17 بجے تک کام\" – اور AI وقت اور کاموں کے ساتھ ایک نیا ٹیب بنا دیتا ہے۔ اگر متن میں دن لکھے ہوں (\"کام کے دنوں میں\")، تو ٹیب انہی دنوں کھلتا ہے، اور مختلف دنوں کی مختلف روٹینز الگ ٹیب بن جاتی ہیں۔ بعد میں سب کچھ معمول کے مطابق بدلا جا سکتا ہے۔",
