    faq_a_secret_room_diary: "صرف آپ۔ ڈائری کے صفحات آپ کے اکاؤنٹ میں محفوظ ہوتے ہیں، اس لیے وہ ہر ڈیوائس پر موجود رہتے ہیں اور کوئی اور انہیں نہیں دیکھ سکتا۔ خفیہ کمرے میں میز پر رکھی جادوئی ڈائری اسے کھولتی ہے، اور موسیقی کے کونے والی ڈائری بھی۔ نئے صفحے کے نیچے ایک تہہ شدہ ماہانہ کیلنڈر ہے: جس دن کوئی صفحہ ہو اس پر ایک نقطہ ہوتا ہے، اور کسی دن کو چھونے سے اس کے صفحات کھلتے ہیں – وہاں صفحہ حذف بھی کیا جا سکتا ہے۔ ڈائری کھل جانے کے بعد اسے مرکزی مینو میں بھی شامل کیا جا سکتا ہے – ڈائری کے اندر یا New Me کی ترتیبات میں موجود سوئچ سے۔",
    faq_a_secret_room_places: "جنگل کے دروازے کا ہر داخلہ اپنی چابی سے کھلتا ہے۔ ان کے پیچھے: سمندر کے سامنے والا برآمدہ (چھوٹی میز پر علاءالدین کا چراغ – چھوتے ہی جنگل کی ایک روح جادوئی دھند میں اس میں سے اٹھتی ہے، گھومتی ہے اور آپ کی خواہش کے بارے میں بات چیت شروع کرتی ہے – دیکھیں “چراغ کا جن کیا کرتا ہے؟”)، گٹار اور ڈائری (گٹار ایک مختصر، پُرسکون دھن بجاتا ہے اور خود بخود رک جاتا ہے، اور درخت پر لٹکے تینوں ریکارڈوں میں سے ہر ایک اپنی جادوئی دھن بجاتا ہے – دوبارہ چھونے سے دھن رک جاتی ہے – اور درخت کے ٹھونٹھ پر رکھی ڈائری لکھنے کے لیے ہے)، سانس لینے کا کمرہ (غروبِ آفتاب کے وقت ایک پُرسکون جھیل – پانی پر ایک کنول کی لالٹین تیرتی ہے: اسے چھوئیں، خواہش لکھیں، اور وہ اسے لے کر جھیل کی گہرائی میں بہت دور بہہ جاتی ہے؛ جادو کی چھڑی سے ریت پر وہ لکھا جا سکتا ہے جسے چھوڑنا ہے، اور یہ تب تک رہتا ہے جب تک آپ اسے انگلی سے نہ مٹائیں) اور جنگل کی پگڈنڈی (یہ رات کو کھلتی ہے، اور لالٹینوں کو چھونے سے دن ہو جاتا ہے؛ بڑی شاخ سے ایک جادوئی جھولا لٹکتا ہے، بینچ پر بیٹھا جا سکتا ہے، اور تختی کو چھونے پر وہ قریب آ جاتی ہے – چھ چھوٹے سوالوں والا تختہ جن پر نشان لگایا جا سکتا ہے)۔ بند داخلے پر نظر آتا ہے کہ کتنی چابیاں باقی ہیں۔ پگڈنڈی کے آخر میں ایک چمکتا ہوا دروازہ آبشار کے پاس یوگا تک لے جاتا ہے – اور وہاں سے خود آبشار تک۔",
