    ai_chat_working_schedule: "ایک لمحہ، کیلنڈر میں شامل کیا جا رہا ہے…",
    ai_chat_working_table: "ایک لمحہ، جدول بنایا جا رہا ہے…",
    dev_weather_preview_label: "پیش منظر – صرف آپ کے اکاؤنٹ میں:",
    faq_a_ai_chat: "ببل پر ٹیپ کریں اور چیٹ کھل جائے گی۔ منتخب کریں کہ کیا کرنا ہے – کیلنڈر کے لیے کچھ، آپ نے کیا کھایا، ترکیب کی تصویر یا نیا جدول – یا بس لکھ دیں، اسسٹنٹ خود سمجھ جائے گا۔ 🎙️ پر ٹیپ کر کے ٹائپ کرنے کے بجائے بولا بھی جا سکتا ہے۔ کیلنڈر کے لیے ایک بار، ہر ہفتے یا ہر روز منتخب کیا جا سکتا ہے۔ جواب چیٹ میں آتا ہے، اور وہاں سے کسی اور کام کی طرف بڑھا جا سکتا ہے یا کیلنڈر / کھایا ہوا کھولا جا سکتا ہے۔",
    faq_a_new_me_hall: "New Me ایک جادوئی جنگل کے دروازے پر کھلتا ہے، اور اس کا ہر داخلہ ایک جگہ ہے: دیو قامت درخت کا گول دروازہ خفیہ کمرے میں لے جاتا ہے، کھوکھلا تنا – سمندر کے سامنے والے برآمدے تک، کھمبی والا گھر – گٹار اور ڈائری تک، بید کی چھوٹی محراب – سانس لینے کے کمرے تک، بید کی بڑی محراب – جنگل کی پگڈنڈی تک، اور سیڑھی والی پھولوں کی محراب، چھت کھلنے کے بعد، اوپر ستاروں والی چھت تک لے جاتی ہے۔ بند داخلے پر تالا نظر آتا ہے۔ پگڈنڈی پر آپ کا کردار، Sky، تیرتا ہے، اور چاروں طرف کھیل کے بٹن ہیں: اگلا مشن، ہفتے کا چیلنج، پورے New Me والا جادوئی بیگ، دنیا کا نقشہ اور ٹولز۔ اوپر چابیوں پر ٹیپ کرنے سے بتایا جاتا ہے کہ چابیاں کیسے ملتی ہیں۔",
    faq_a_new_me_routine_meals: "جب New Me میں کھانے طے ہوں اور میری روٹین میں بھی کھانے ہوں، تو New Me پوچھتا ہے کہ کیا انہیں چھپا کر ان کی جگہ New Me کے کھانے دکھائے جائیں – تاکہ کچھ بھی دو بار نظر نہ آئے۔ پھر میری روٹین New Me کے کھانے ان کے اوقات پر دکھاتی ہے، 💎 اور ✓ کے ساتھ؛ کھانے کے نام پر ٹیپ کرنے سے دوسرا کھانا چننے یا اس کا وقت بدلنے کی ونڈو کھلتی ہے، وہیں روٹین کے اوپر۔ کچھ بھی حذف نہیں ہوتا: وہ New Me کی ⚙️ ترتیبات ← روٹین میں کھانے سے واپس آ جاتے ہیں، یا میری روٹین کے ⚙️ میں “New Me کے ساتھ ہم آہنگی” بند کرنے سے۔ فعال New Me نہ ہو تو وہ خود بخود واپس آ جاتے ہیں۔",
    faq_a_room_computer: "یہ ایک چھوٹی سی چیٹ ہے جو “اب تک آپ کا دن کیسا گزر رہا ہے؟” سے شروع ہوتی ہے – اچھا، مصروف یا مشکل – اور قدم بہ قدم آپ کے ساتھ آگے بڑھتی ہے، آخر میں ایک چھوٹے مشن تک (جسے سیدھا 'میرا دن' میں بھی ڈالا جا سکتا ہے)۔ جوابوں پر ٹیپ کیا جا سکتا ہے یا کھل کر لکھا جا سکتا ہے – جو لکھا جائے وہ سب سے قریبی جواب سے جڑ جاتا ہے۔ “↩ واپس” ایک قدم پیچھے لے جاتا ہے تاکہ مختلف جواب دیا جا سکے، اور “نئی چیٹ” کسی بھی لمحے شروع سے شروع کرتی ہے۔ مصروف یا مشکل دن کے بعد اسی دن بعد میں کمپیوٹر پر لوٹا جا سکتا ہے: “پھر سے یہاں ہوں...” بات چیت آگے بڑھاتا ہے۔ نیچے کی سبز روشنی کمپیوٹر کو بند اور چالو کرتی ہے۔ صرف انتخاب محفوظ ہوتے ہیں، صرف اسی ڈیوائس پر اور صرف دن کے اختتام تک۔",
