    faq_a_good_things: "شام کو (18:00 سے) تاریخ کے نیچے ایک چھوٹا بٹن نظر آتا ہے: آج ہونے والی زیادہ سے زیادہ 3 اچھی باتیں لکھیں – ایک بھی کافی ہے۔ وہ محفوظ ہو جاتی ہیں، اور 'پچھلے دن' میں پہلے لکھا ہوا نظر آتا ہے۔ 'آج رات نہیں' اسے کل تک چھپا دیتا ہے، اور ترتیبات > تخصیص اور کیلنڈر میں اسے مکمل بند بھی کیا جا سکتا ہے۔",
