    faq_a_home_streak: "یہ گنتا ہے کہ لگاتار کتنے دن کم از کم ایک ✓ رہا – میرا دن، میری روٹین، میرے اہداف یا New Me میں کچھ بھی۔ یہ 2 دن سے نظر آتا ہے۔ اگر آج ابھی ✓ نہیں تو سلسلہ ٹوٹا نہیں – ابھی پورا دن باقی ہے۔ اور اگر سلسلہ ختم ہو جائے تو یہ بس خاموشی سے غائب ہو جاتا ہے، بغیر کسی احساسِ جرم کے۔",
    faq_a_home_weather: "ترتیبات > تخصیص اور کیلنڈر میں 'ہوم اسکرین کے آسمان میں موسم' آن کریں اور مقام کی اجازت دیں۔ پھر ہوم اسکرین کا آسمان آپ کی جگہ کا اصل موسم دکھاتا ہے – دھوپ (رات کو چاند اور ستارے)، بادل، بارش، برف، طوفان یا دھند – ہر تھیم میں، اور تقریباً ہر 40 منٹ میں اپ ڈیٹ ہوتا ہے۔ اندازاً مقام (تقریباً 1 کلومیٹر تک گول کیا ہوا) صرف آپ کی ڈیوائس پر رہتا ہے اور ہمارے سرور کے ذریعے MET Norway سے دیکھا جاتا ہے۔ یہ پہلے سے بند ہوتا ہے۔ سوئچ کے نیچے لکھا ہوتا ہے کہ ابھی باہر موسم کیسا ہے – مثلاً ⛅ جزوی ابر آلود، اسی لیے آسمان میں دھوپ اور بادل دونوں نظر آتے ہیں۔",
