    faq_a_bag_pockets: "ہر نوٹ بک، ٹیبل اور کام کو دوسری جیب میں منتقل کیا جا سکتا ہے: اس کی ونڈو کھولیں (نوٹ بک میں 🎨، ٹیبل میں ✏️، یا کام پر ٹیپ کریں) اور جیب چنیں۔ جیب کا نام، آئیکن یا رنگ بدلنے کے لیے اسے کھول کر نام کے ساتھ والے ✏️ پر ٹیپ کریں۔ جیب حذف کرنے سے اس کے اندر کی ہر چیز حذف ہو جاتی ہے، اس لیے جو رکھنا ہو اسے پہلے منتقل کر دیں۔ نئے بیگ کے ساتھ آنے والی مثالیں بھی اسی طرح کام کرتی ہیں – انہیں کسی بھی وقت بدلا یا حذف کیا جا سکتا ہے۔",
