    faq_a_google_calendar_reconnect: "عام طور پر ایسا اس لیے ہوتا ہے کہ Google نے ایپ کی رسائی ختم کر دی – مثلاً کچھ عرصے بعد، پاس ورڈ تبدیل کرنے کے بعد، یا اگر آپ کے Google اکاؤنٹ میں رسائی ہٹا دی گئی ہو۔ ایسا ہونے پر ترتیبات میں '🔄 دوبارہ کنیکٹ کریں' بٹن کے ساتھ ایک انتباہ نظر آتا ہے کہ Google Calendar سے کنکشن کی میعاد ختم ہو گئی ہے (اور ایپ کھولنے پر ایک مختصر پیغام بھی نظر آتا ہے)۔ بٹن پر ٹیپ کریں اور دوبارہ منظوری دیں – اس دوران آپ نے جو کچھ بھی شامل کیا، وہ ایک دو منٹ میں Google کو بھیج دیا جاتا ہے، اس لیے کچھ بھی ضائع نہیں ہوتا۔",
    faq_q_google_calendar_reconnect: "میں نے جو ایونٹ شامل کیا، وہ Google Calendar تک کیوں نہیں پہنچا؟",
    google_calendar_reconnect_toast: "Google Calendar کو دوبارہ کنیکٹ کرنا ہوگا – اسے ترتیبات میں ٹھیک کیا جا سکتا ہے ⚙️",
    settings_google_calendar_reconnect_btn: "🔄 دوبارہ کنیکٹ کریں",
    settings_google_calendar_reconnect_warning: "⚠️ Google Calendar سے کنکشن کی میعاد ختم ہو گئی ہے، اس لیے نئے ایونٹس Google تک نہیں پہنچ رہے۔ دوبارہ کنیکٹ کریں – اس دوران شامل کی گئی ہر چیز کنیکٹ ہوتے ہی بھیج دی جائے گی۔",
    apptour_m_books_link: "مکمل کرنے کی تاریخ سے 'میرا دن' میں روزانہ پڑھنے کا کام شامل ہو جاتا ہے، اور مکمل ہونے والی کتابیں 'میرے اہداف' کے کسی مطالعے کے ہدف میں گنی جا سکتی ہیں۔",
    apptour_m_books_text: "مطالعے کا ایک پُرسکون گوشہ: خریدنے والی، آگے پڑھنے والی، ابھی پڑھی جا رہی اور پڑھی ہوئی کتابیں – پیش رفت کی پٹی، مکمل کرنے کی تاریخ اور مکمل ہونے والی کتابوں کی شیلف کے ساتھ۔",
    faq_a_books_deadline: "جو کتاب پڑھی جا رہی ہے، اس کی تفصیلات میں 'مکمل کرنے کی تاریخ' سیٹ کریں (یا اس کے کارڈ پر 📅 پر ٹیپ کریں)۔ کارڈ پر باقی دن اور روزانہ درکار صفحات نظر آتے ہیں، اور 'میرا دن' میں '📖 15 صفحات پڑھیں' جیسا ایک روزانہ کام آتا ہے – اس پر نشان لگانے سے وہ صفحات کتاب میں شامل ہو جاتے ہیں، اور نشان ہٹانے پر واپس کم ہو جاتے ہیں۔ یہ تعداد ہر دن کے آغاز میں طے ہوتی ہے، اس بنیاد پر کہ کتاب کہاں تک پڑھی جا چکی ہے۔ کتابوں کو کسی ہدف میں گننے کے لیے '🎯 مطالعے کے ہدف سے جوڑیں' پر ٹیپ کریں اور 'میرے اہداف' سے 'ہدف نمبر تک گنتی' والا ہدف چنیں – ہر مکمل ہونے والی کتاب +1 کا اضافہ کرتی ہے، اور کتاب کو واپس لے جانے پر وہ +1 ہٹ جاتا ہے۔ صفحہ کم کرنے یا صرف آزمانے کے لیے 'پوری پڑھ لی 🎉' پر ٹیپ کرنے سے کام غائب نہیں ہوتا: کم صفحہ پڑھائی نہیں بلکہ درستی شمار ہوتا ہے، اور جو کتاب ✅ پڑھ لی سے واپس 📖 پڑھی جا رہی میں لائی جائے، وہ اسی صفحے پر لوٹ آتی ہے جہاں تھی (اگر وہ معلوم نہ ہو تو ایپ پوچھتی ہے کہ ابھی کون سا صفحہ چل رہا ہے)۔",
    faq_q_books_deadline: "مکمل کرنے کی تاریخ، روزانہ پڑھنے کا کام اور مطالعے کا ہدف کیسے کام کرتے ہیں؟",
    faq_a_books_what: "مینو میں 'فہرستیں' کے تحت '📚 مطالعے کا گوشہ' کھولیں۔ اس میں چار ٹیب ہیں: 🛒 خریدنی ہیں، 📚 پڑھنی ہیں، 📖 پڑھی جا رہی اور ✅ پڑھ لی۔ '+ کتاب' پر ٹیپ کریں اور نام لکھیں – اگر کتاب Open Library میں مل جائے تو ایک ٹیپ میں اس کا کور، مصنف اور صفحات بھر جاتے ہیں (ورنہ اسے ایک رنگ برنگا کور ملتا ہے)۔ ایک ٹیپ سے کتاب کو آگے بڑھائیں: 'خرید لی ✓'، '▶ پڑھنا شروع کریں' اور 'پوری پڑھ لی 🎉'۔ پڑھتے وقت اپنا صفحہ اپ ڈیٹ کریں (یا +10 / +25 پر ٹیپ کریں) اور پیش رفت کی پٹی اور اپنے 🔥 مطالعے کے سلسلے کو بڑھتے دیکھیں۔ مکمل ہونے والی کتابیں لکڑی کی شیلف پر آپ کی ⭐ ریٹنگ اور پسندیدہ سطر کے ساتھ سجتی ہیں – کسی کتاب پر ٹیپ کر کے اسے دوبارہ کھولیں۔ نام سے نہیں ملا؟ مصنف کا نام لکھنے سے اس کی کتابیں ظاہر ہوتی ہیں – اور جب Open Library کم ڈھونڈ پائے تو Google Books میں بھی تلاش کیا جاتا ہے۔",
    faq_q_books_what: "جو کتابیں خریدنی اور پڑھنی ہیں، ان کا حساب کیسے رکھوں؟",
