    faq_a_new_me_tracking: "New Me کے اوپر اگلے مشن پر ٹیپ کریں اور پھر ✓ کھا لیا پر تاکہ اگلا کھانا کھایا ہوا نشان زد ہو جائے – ہر کھانے پر ✓ کے ساتھ پورا مینو “پورا دن” میں ہے (ایک طرف)، اور آج کے کھانے ہوم اسکرین پر میرا دن میں بھی نظر آتے ہیں – وہاں کسی کھانے پر ٹیپ کرنے (یا اس پر ماؤس لے جانے) سے بالکل ٹھیک دکھائی دیتا ہے کہ کیا کھانا ہے، ✓ اور تبدیل کریں کے ساتھ۔ سب کچھ روزانہ کھانے کے ٹریکر سے ہم آہنگ رہتا ہے: پلان کے کھانے، مشروبات اور جو کچھ بھی کہیں اور شامل کیا جائے (جیسے فوری اضافے سے کافی)، New Me اور میرا دن میں ساتھ گنے جاتے ہیں – پہلے سے لکھا کچھ بھی مٹتا نہیں، اور ✓ ہٹانے سے صرف New Me والا حصہ ہٹتا ہے۔ جب آج کے سارے کھانے نشان زد ہو جاتے ہیں تو ایک چھوٹا جشن ہوتا ہے۔ “مشروبات” میں دن کے مشروبات درج کریں – سب ملا کر ~150 کیلوریز تک، یعنی تقریباً 3 مشروبات، ہر ایک ~50 کیلوریز تک۔ بس مشروب کا نام لکھیں، کیلوریز AI سے خود بخود بھر جاتی ہیں۔ کافی/چائے کی دونوں قطاروں میں “دودھ؟ کتنا؟” کا خانہ بھی ہے (جیسے “تھوڑا” یا “50 ملی لیٹر”)، اور حساب اپڈیٹ ہو جاتا ہے؛ عدد شامل کرنے سے پہلے اور بعد میں بھی بدلا جا سکتا ہے۔ نام اور کیلوریز والا مشروب آگے بڑھتے ہی خود بخود محفوظ ہو جاتا ہے – شامل کریں پر ٹیپ کرنا ضروری نہیں۔ کسی مشروب کے ساتھ ☆ پر ٹیپ کریں تو وہ معمول کے مشروب کے طور پر محفوظ ہو جاتا ہے – معمول کے مشروبات مشروبات کارڈ کے اوپر بٹن کی صورت میں نظر آتے ہیں، اور ایک ٹیپ انہیں دن میں شامل کر دیتا ہے۔ ⭐ کسی کھانے کو محفوظ کھانے کے طور پر محفوظ کرتا ہے۔ “روزانہ جدول” کیلوریز اور پروٹین کے ساتھ دکھاتا ہے کہ کیا کھایا۔ ہوم اسکرین کے اوپر فوکس موڈ کے ساتھ چھوٹا 💎 اسے سیدھا کھولتا ہے۔ کیلوریز اور پروٹین کی قدریں AI کے اندازے ہیں اور ان میں غلطیاں ہو سکتی ہیں۔ پورا نہیں کھایا؟ نشان زد کھانے کے نیچے “پورا نہیں کھایا؟” حصے کا ایک چوتھائی، آدھا یا تین چوتھائی کم کر دیتا ہے – یا جو آپ لکھیں، حساب لگا کر – اور دن کی کیلوریز اپڈیٹ ہو جاتی ہیں۔",
