    faq_q_daily_focus_prompt: "وہ چھوٹی یاددہانی کیا ہے جو پوچھتی ہے کہ آج میرے لیے سب سے اہم کام کیا ہے؟", faq_a_daily_focus_prompt: "یہ ایک پریمیم روزانہ یاددہانی ہے: دن میں ایک بار AI اسسٹنٹ کے آئیکن پر ایک چھوٹا “1” بیج ظاہر ہوتا ہے۔ بیج پر ٹیپ کریں تو ایک بلبلہ کھلتا ہے جو پوچھتا ہے کہ آج آپ کے لیے سب سے اہم کیا ہے، اور اس میں فوراً 5 تیار تجاویز نظر آتی ہیں (یہ روز بدلتی ہیں، پورے سال مختلف موضوعات میں گھومتی رہتی ہیں تاکہ تازہ رہیں) اور اپنا جواب لکھنے کے لیے 'دیگر' - آپ ایک سے زیادہ چن سکتے ہیں۔ شامل کریں پر ٹیپ کریں، اور آپ کے انتخاب 'میرا دن' کے اوپر چھوٹے یاددہانی ٹیگز کی صورت میں نظر آئیں گے (یہ نشان لگانے والے کام نہیں ہیں)۔ اگر آپ اسے ✕ سے بند کریں یا باہر ٹیپ کریں تو بیج غائب ہونے کے بجائے دن کے باقی حصے کے لیے صرف مدھم ہو جاتا ہے۔ یہ پہلے سے آن ہوتی ہے، لیکن آپ اسے ترتیبات > تخصیص اور کیلنڈر میں بند کر سکتے ہیں۔ آج مناسب نہیں؟ '🌙 آج نہیں' پر ٹیپ کریں – بیج کل تک غائب ہو جاتا ہے، پھر سوال معمول کے مطابق واپس آ جاتا ہے۔ تجاویز میں سے ایک آپ کی اپنی زندگی سے آتی ہے – مہینے کے ہدف کا اگلا قدم یا آج کا مطالعہ۔ ہر دن نئے سرے سے شروع ہوتا ہے۔",
